<script setup lang="ts">
import { computed } from 'vue'
import { ArrowDown, ArrowRight, ArrowUpRight, Check, CircleHelp, Code2, ExternalLink, Eye, GitBranch, ListChecks, Monitor, Play, ShieldCheck, SquareTerminal, Video } from 'lucide-vue-next'
import CopyButton from './components/CopyButton.vue'
import { siteConfig } from '../site/config'
import { architectureSteps, comparisons, contributionSteps, demoSegments, demoSpokenWords, demoTaskArguments, featureShowcase, getYouTubeEmbedUrl, submissionChecklist } from './hackathon'

const videoEmbed = computed(() => getYouTubeEmbedUrl(siteConfig.videoUrl))
const validRepository = computed(() => {
  try { const url = new URL(siteConfig.repositoryUrl); return url.protocol === 'https:' ? url.href.replace(/\/$/, '') : null } catch { return null }
})
const scriptText = computed(() => demoSegments.map(segment => `${segment.time} | ${segment.title}\nScreen action: ${segment.action}\nNarration: ${segment.narration}\nTools: ${segment.tools}\nExpected result: ${segment.result}`).join('\n\n'))
function openRecordingScript() { document.getElementById('recording-script')?.setAttribute('open', '') }
function checklistState(key: string) {
  if (key === 'video') return videoEmbed.value ? { label: 'Check public access and audio', state: 'review' } : { label: '[YOUTUBE_URL] missing', state: 'missing' }
  if (key === 'repository') return siteConfig.repositoryPublic ? { label: 'Public access verified', state: 'available' } : { label: validRepository.value ? 'Visibility not verified' : '[REPOSITORY_URL] missing', state: 'review' }
  if (key === 'live') return siteConfig.liveUrl && !siteConfig.liveUrl.startsWith('[') ? { label: 'Production URL configured', state: 'available' } : { label: '[LIVE_URL] missing', state: 'missing' }
  if (key === 'license') return siteConfig.license ? { label: `${siteConfig.license} in this build; publish source`, state: 'review' } : { label: 'License needed', state: 'missing' }
  if (key === 'source' || key === 'readme') return { label: 'Publish source changes', state: 'review' }
  if (key === 'review') return { label: 'Owner review required', state: 'review' }
  return { label: 'Included in the project', state: 'available' }
}
</script>

<template>
  <article class="hackathon-page" aria-labelledby="hackathon-title">
    <header class="hackathon-hero">
